CREATE TABLE "MarketplaceSellerProfile" ("id" TEXT PRIMARY KEY,"userId" TEXT NOT NULL UNIQUE,"displayName" TEXT,"bio" TEXT,"regionLabel" TEXT,"contactPreference" TEXT NOT NULL DEFAULT 'IN_APP',"publicPhone" TEXT,"showPhone" BOOLEAN NOT NULL DEFAULT false,"updatedAt" TIMESTAMP(3) NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "MarketplaceSellerProfile_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE);
CREATE TABLE "MarketplaceFavorite" ("id" TEXT PRIMARY KEY,"userId" TEXT NOT NULL,"listingId" TEXT NOT NULL,"status" TEXT NOT NULL DEFAULT 'ACTIVE',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "MarketplaceFavorite_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE,CONSTRAINT "MarketplaceFavorite_listingId_fkey" FOREIGN KEY ("listingId") REFERENCES "MarketplaceListing"("id") ON DELETE RESTRICT ON UPDATE CASCADE);
CREATE UNIQUE INDEX "MarketplaceFavorite_userId_listingId_key" ON "MarketplaceFavorite"("userId","listingId");
CREATE INDEX "MarketplaceFavorite_userId_status_updatedAt_idx" ON "MarketplaceFavorite"("userId","status","updatedAt");
CREATE INDEX "MarketplaceFavorite_listingId_status_idx" ON "MarketplaceFavorite"("listingId","status");
CREATE TABLE "MarketplaceMessage" ("id" TEXT PRIMARY KEY,"senderId" TEXT NOT NULL,"recipientId" TEXT NOT NULL,"listingId" TEXT,"orderId" TEXT,"body" TEXT NOT NULL,"readAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "MarketplaceMessage_senderId_fkey" FOREIGN KEY ("senderId") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE,CONSTRAINT "MarketplaceMessage_recipientId_fkey" FOREIGN KEY ("recipientId") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE,CONSTRAINT "MarketplaceMessage_listingId_fkey" FOREIGN KEY ("listingId") REFERENCES "MarketplaceListing"("id") ON DELETE RESTRICT ON UPDATE CASCADE,CONSTRAINT "MarketplaceMessage_orderId_fkey" FOREIGN KEY ("orderId") REFERENCES "MarketplaceOrder"("id") ON DELETE RESTRICT ON UPDATE CASCADE);
CREATE INDEX "MarketplaceMessage_senderId_createdAt_idx" ON "MarketplaceMessage"("senderId","createdAt");
CREATE INDEX "MarketplaceMessage_recipientId_readAt_createdAt_idx" ON "MarketplaceMessage"("recipientId","readAt","createdAt");
CREATE INDEX "MarketplaceMessage_listingId_createdAt_idx" ON "MarketplaceMessage"("listingId","createdAt");
CREATE INDEX "MarketplaceMessage_orderId_createdAt_idx" ON "MarketplaceMessage"("orderId","createdAt");
CREATE TABLE "MarketplaceRFQ" ("id" TEXT PRIMARY KEY,"buyerId" TEXT NOT NULL,"title" TEXT NOT NULL,"category" TEXT NOT NULL,"description" TEXT NOT NULL,"quantity" DOUBLE PRECISION NOT NULL,"unit" TEXT NOT NULL,"targetUnitPrice" DECIMAL(14,2),"currency" TEXT NOT NULL DEFAULT 'INR',"deliveryRegion" TEXT,"neededBy" TIMESTAMP(3),"status" TEXT NOT NULL DEFAULT 'OPEN',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "MarketplaceRFQ_buyerId_fkey" FOREIGN KEY ("buyerId") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE);
CREATE INDEX "MarketplaceRFQ_status_category_createdAt_idx" ON "MarketplaceRFQ"("status","category","createdAt");
CREATE INDEX "MarketplaceRFQ_buyerId_status_createdAt_idx" ON "MarketplaceRFQ"("buyerId","status","createdAt");
CREATE TABLE "MarketplaceRFQResponse" ("id" TEXT PRIMARY KEY,"rfqId" TEXT NOT NULL,"sellerId" TEXT NOT NULL,"unitPrice" DECIMAL(14,2) NOT NULL,"availableQuantity" DOUBLE PRECISION NOT NULL,"note" TEXT,"validUntil" TIMESTAMP(3),"status" TEXT NOT NULL DEFAULT 'SUBMITTED',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "MarketplaceRFQResponse_rfqId_fkey" FOREIGN KEY ("rfqId") REFERENCES "MarketplaceRFQ"("id") ON DELETE RESTRICT ON UPDATE CASCADE,CONSTRAINT "MarketplaceRFQResponse_sellerId_fkey" FOREIGN KEY ("sellerId") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE);
CREATE UNIQUE INDEX "MarketplaceRFQResponse_rfqId_sellerId_key" ON "MarketplaceRFQResponse"("rfqId","sellerId");
CREATE INDEX "MarketplaceRFQResponse_sellerId_status_createdAt_idx" ON "MarketplaceRFQResponse"("sellerId","status","createdAt");
CREATE INDEX "MarketplaceRFQResponse_rfqId_status_createdAt_idx" ON "MarketplaceRFQResponse"("rfqId","status","createdAt");
